<template>
  <div class="pagination-component">
    <!-- Previous 按钮 -->
    <div 
      class="pagination-btn prev-btn"
      :class="{'disabled': currentPage <= 1}"
      @click="handlePrevious"
    >
      <div class="btn-icon">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <path d="M10 4L6 8L10 12" stroke="currentColor" stroke-width="1.33" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </div>
      <span class="btn-text">{{ t('previous') }}</span>
    </div>

    <!-- 当前页码按钮 -->
    <div class="pagination-btn page-btn current-page-btn">
      <span class="page-number">{{ currentPage }}</span>
    </div>

    <!-- Next 按钮 -->
    <div 
      class="pagination-btn next-btn"
      :class="{'disabled': currentPage >= totalPages}"
      @click="handleNext"
    >
      <span class="btn-text">{{ t('next') }}</span>
      <div class="btn-icon">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
          <path d="M6 4L10 8L6 12" stroke="currentColor" stroke-width="1.33" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </div>
    </div>

    <!-- 分隔线 -->
    <div v-if="showPageSizes || showJumper" class="divider"></div>

    <!-- 每页条数选择器 -->
    <div v-if="showPageSizes" class="page-size-selector">
      <el-select 
        v-model="currentPageSize" 
        @change="handlePageSizeChange"
        class="size-select"
        popper-class="pagination-select-dropdown"
      >
        <el-option
          v-for="size in pageSizes"
          :key="size"
          :label="size.toString()"
          :value="size"
        />
      </el-select>
    </div>

    <!-- 分隔线 -->
    <div v-if="showJumper" class="divider"></div>

    <!-- 页面跳转功能 -->
    <div v-if="showJumper" class="page-jumper">
      <div class="jump-input-wrapper">
        <input 
          v-model="jumpPageValue"
          type="number"
          :min="1"
          :max="totalPages"
          class="jump-input"
          @keyup.enter="handleJump"
          @blur="handleInputChange"
        />
      </div>
      <span class="jump-divider">/</span>
      <span class="total-pages">{{ totalPages }}</span>
      <div 
        class="pagination-btn go-btn"
        @click="handleJump"
        :class="{'disabled': !isValidJumpPage}"
      >
        <span class="btn-text">{{ t('go') }}</span>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted } from 'vue';
import { useI18n } from 'vue-i18n';
import { ElMessage } from 'element-plus';

// 多语言支持
const { t } = useI18n();

// Props定义
const props = defineProps({
  // 当前页码
  currentPage: {
    type: Number,
    default: 1
  },
  // 每页条数
  pageSize: {
    type: Number,
    default: 20
  },
  // 总条数
  total: {
    type: Number,
    default: 0
  },
  // 每页条数选项
  pageSizes: {
    type: Array,
    default: () => [20, 30, 40, 50]
  },
  // 是否显示每页条数选择器
  showPageSizes: {
    type: Boolean,
    default: true
  },
  // 是否显示页面跳转功能
  showJumper: {
    type: Boolean,
    default: true
  }
});

// Events定义
const emit = defineEmits(['current-change', 'size-change']);

// 响应式数据
const currentPageSize = ref(props.pageSize);
const jumpPageValue = ref(1); // 默认显示第一页

// 计算属性
const totalPages = computed(() => {
  return Math.ceil(props.total / currentPageSize.value) || 1;
});

const isValidJumpPage = computed(() => {
  const page = parseInt(jumpPageValue.value);
  return page >= 1 && !isNaN(page);
});

// 监听pageSize变化
watch(() => props.pageSize, (newVal) => {
  currentPageSize.value = newVal;
});

// 监听当前页码变化，同步到跳转输入框
watch(() => props.currentPage, (newVal) => {
  jumpPageValue.value = newVal;
});

// 组件挂载时初始化跳转输入框值
onMounted(() => {
  jumpPageValue.value = props.currentPage;
});

// 事件处理
const handlePrevious = () => {
  if (props.currentPage > 1) {
    emit('current-change', props.currentPage - 1);
  }
};

const handleNext = () => {
  if (props.currentPage < totalPages.value) {
    emit('current-change', props.currentPage + 1);
  }
};

const handlePageSizeChange = (newSize) => {
  emit('size-change', newSize);
};

// 输入验证处理
const handleInputChange = () => {
  const inputValue = jumpPageValue.value;
  
  // 如果输入为空字符串或非数字，设置为当前页
  if (inputValue === '' || inputValue === null || inputValue === undefined) {
    jumpPageValue.value = props.currentPage;
    return;
  }
  
  const page = parseInt(inputValue);
  
  // 如果输入不是数字或小于1，重置为当前页并提示
  if (isNaN(page) || page < 1) {
    jumpPageValue.value = props.currentPage;
    ElMessage.warning(t('invalidPageNumber'));
    return;
  }
  
  // 如果输入超过最大页数，设置为最大页数并自动跳转
  if (page > totalPages.value) {
    jumpPageValue.value = totalPages.value;
    // 如果不在最后一页，则自动跳转到最后一页
    if (props.currentPage !== totalPages.value) {
      emit('current-change', totalPages.value);
    }
    return;
  }
};

const handleJump = () => {
  let page = parseInt(jumpPageValue.value);
  const originalInput = page; // 保存原始输入值
  
  // 输入验证
  if (isNaN(page) || page < 1) {
    ElMessage.warning(t('invalidPageNumber'));
    jumpPageValue.value = props.currentPage;
    return;
  }
  
  // 如果输入超过最大页数，跳转到最后一页
  if (page > totalPages.value) {
    page = totalPages.value;
    jumpPageValue.value = totalPages.value;
    // 即使当前已经是最后一页，如果用户输入了超过最大页码的数字，也应该触发跳转
    // 这样可以让用户知道已经到了最后一页
    if (originalInput > totalPages.value) {
      emit('current-change', page);
      return;
    }
  }
  
  if (page === props.currentPage) {
    // 如果跳转到当前页，不需要触发事件
    return;
  }
  
  emit('current-change', page);
};
</script>

