<!--
  宽高比显示组件 - AspectRatio Component
  
  功能说明：
  1. 接收宽高比参数（如 16:9, 4:3 等）
  2. 显示符合比例的矩形框
  3. 限制最大尺寸为 31px
  4. 使用固定颜色 #D1D5DB
  
  使用示例：
  <AspectRatio aspectRatio="16:9" />
  <AspectRatio aspectRatio="4:3" />
  <AspectRatio aspectRatio="1:1" />
-->

<template>
  <div 
    class="aspect-ratio-container"
    :style="containerStyle"
  >
  </div>
</template>

<script setup>
import { computed } from 'vue';
import { convertStyleObject } from '@/utils/px-to-rem';

// Props 定义
const props = defineProps({
  aspectRatio: {
    type: String,
    default: '1:1',
    validator: (value) => {
      // 验证格式是否为 "数字:数字"
      return /^\d+:\d+$/.test(value);
    }
  }
});

// 计算宽度值
const widthRatio = computed(() => {
  return parseInt(props.aspectRatio.split(':')[0]);
});

// 计算高度值
const heightRatio = computed(() => {
  return parseInt(props.aspectRatio.split(':')[1]);
});

// 计算实际显示尺寸
const containerStyle = computed(() => {
  const maxSize = 31; // 最大尺寸限制
  
  // 计算比例
  const ratio = widthRatio.value / heightRatio.value;
  
  let width, height;
  
  if (ratio >= 1) {
    // 宽度大于等于高度的情况
    width = maxSize;
    height = Math.round(maxSize / ratio);
  } else {
    // 高度大于宽度的情况
    height = maxSize;
    width = Math.round(maxSize * ratio);
  }
  
  return convertStyleObject({
    width: `${width}px`,
    height: `${height}px`,
    borderRadius: '2px',
    flexShrink: 0 // 防止在flex容器中被压缩
  });
});
</script>

<style scoped lang="scss">
.aspect-ratio-container {
  // 基础样式
  border: 1px solid #D1D5DB;
  box-sizing: border-box;
  
  // 确保矩形显示清晰
  min-width: 8px;
  min-height: 8px;
  margin-bottom: 4px;
  
  // 过渡动画，提升用户体验
  transition: all 0.2s ease;
}
</style>