<!--
  统一图片/视频详情弹框组件 - Unified Image/Video Detail Dialog
  
  实现思路：
  1. 使用通用弹框组件作为基础
  2. 通过mode属性控制显示模式：'zoom' | 'enhance' | 'edit' | GenerationType.TEXT_TO_VIDEO | GenerationType.IMAGE_TO_VIDEO
  3. 左侧显示图片或视频（根据模式不同）
  4. 右侧显示配置信息（根据模式显示不同字段）
  5. 支持图片缩放和拖拽功能，视频播放控制
  6. 基于Figma设计图的精确样式实现
-->

<template>
  <CommonDialog
    v-model="dialogVisible"
    :close-on-click-modal="true"
    :close-on-press-escape="true"
    @close="handleClose"
    :isScale="false"
  >
    <div class="image-detail-dialog" :class="[`mode-${mode}`]">
      <!-- 左侧图片区域 -->
      <div class="image-section">
        <!-- 放大模式：单张图片 -->
        <template v-if="mode === 'zoom'">
          <l-img 
            :src="currentImage?.imageUrl || ''" 
            w="100%" 
            h="100%" 
            fit="contain"
            class="zoom-image"
            @error="handleImageError"
          />
        </template>

        <!-- 编辑模式：单张图片 -->
        <template v-if="mode === 'edit'">
          <l-img 
            :src="currentImage?.imageUrl || ''" 
            w="100%" 
            h="100%" 
            fit="contain"
            class="edit-image"
            @error="handleImageError"
          />
        </template>

        <!-- 增强模式：单张图片 -->
        <template v-if="mode === 'enhance'">
          <l-img 
            :src="currentImage?.imageUrl || ''" 
            w="100%" 
            h="100%" 
            fit="contain"
            class="enhance-image"
            @error="handleImageError"
          />
        </template>

        <!-- 文生视频模式：视频播放器 -->
        <template v-if="mode === GenerationType.TEXT_TO_VIDEO">
          <l-video
            :src="currentVideo?.videoUrl"
            w="100%"
            h="100%"
            :show-controls="true"
            :muted="false"
            :preload="'metadata'"
            fit="contain"
            radius="8px"
            style="background-color: #000;"
            @error="handleVideoError"
            @loadedmetadata="handleVideoLoaded"
            @timeupdate="updateTime"
            @play="handleVideoPlay"
            @pause="handleVideoPause"
            class="video-player"
          />
        </template>

        <!-- 图生视频模式：视频播放器 -->
        <template v-if="mode === GenerationType.IMAGE_TO_VIDEO">
          <l-video
            :src="currentVideo?.videoUrl"
            w="100%"
            h="100%"
            :show-controls="true"
            :muted="false"
            :preload="'metadata'"
            fit="contain"
            radius="8px"
            @error="handleVideoError"
            @loadedmetadata="handleImgToVideoLoaded"
            @timeupdate="updateImgToVideoTime"
            @play="handleImgToVideoPlay"
            @pause="handleImgToVideoPause"
            class="video-player"
          />
        </template>

        <!-- 风格转换视频模式：视频播放器 -->
        <template v-if="mode === GenerationType.STYLE_CHANGE_VIDEO">
          <l-video
            :src="currentVideo?.videoUrl"
            w="100%"
            h="100%"
            :show-controls="true"
            :muted="false"
            :preload="'metadata'"
            fit="contain"
            radius="8px"
            @error="handleVideoError"
            class="video-player"
          />
        </template>
      </div>

      <!-- 右侧配置信息区域 -->
      <div class="config-section">
        <!-- 标题 -->
        <h2 class="config-title">{{ mode === GenerationType.TEXT_TO_VIDEO || mode === GenerationType.IMAGE_TO_VIDEO ? t('generateVideo') : t('generateImage') }}</h2>
        <p class="config-subtitle" v-if="mode !== GenerationType.TEXT_TO_VIDEO && mode !== GenerationType.IMAGE_TO_VIDEO">{{ t('selectStyleToGenerate') }}</p>

        <!-- 参考图片/视频区域 -->
        <div v-if="mode !== GenerationType.TEXT_TO_VIDEO" class="reference-container">
          <div class="reference-image-frame" :class="{ 
            'zoom-mode': mode === 'zoom', 
            'edit-mode': mode === 'edit',
            'image-to-video-mode': mode === GenerationType.IMAGE_TO_VIDEO
          }">
            <!-- imgToVideo模式显示预览视频 -->
            <template v-if="mode === GenerationType.IMAGE_TO_VIDEO">
              <l-video
                :src="currentVideo?.videoUrl"
                w="100%" 
                h="100%"
                :show-controls="false"
                :muted="true"
                :preload="'metadata'"
                fit="cover"
                radius="8px"
                class="reference-video"
              />
            </template>
            <!-- 其他模式显示图片 -->
            <template v-else>
              <l-img 
                :src="currentImage?.imageUrl || ''" 
                w="100%" 
                h="100%" 
                :fit="mode === 'zoom' || mode === 'edit' ? 'contain' : 'cover'"
                class="reference-image"
                @error="handleImageError"
              />
            </template>
          </div>
          <!-- 增强模式显示描述 -->
          <p v-if="mode === 'enhance'" class="reference-description">
            {{ currentImage?.description || '' }}
          </p>
          <!-- 其他模式显示描述（除了编辑模式和图生视频模式） -->
          <p v-if="mode !== 'edit' && mode !== GenerationType.TEXT_TO_VIDEO && mode !== GenerationType.IMAGE_TO_VIDEO" class="reference-description">
            {{ currentVideo?.description || currentImage?.description || '' }}
          </p>
        </div>

        <!-- Scale Image 配置 (非编辑和非视频模式显示) -->
        <div 
          v-if="mode === 'zoom' || mode === 'enhance'" 
          class="field-group-scale-image"
        >
          <label class="field-label">{{ t('scaleImage') }}</label>
          <span class="scale-text">{{ scaleConfig.scale }}x {{ t('upscale') }}</span>
        </div>

        <!-- 编辑模式专有字段 -->
        <template v-if="mode === 'edit'">
          <!-- URL 显示区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('url') }}</label>
            <div class="field-value url-value">
              {{ currentImage?.imageUrl || 'https://example.com/image.jpg' }}
            </div>
          </div>

          <!-- Prompt 显示区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('prompt') }}</label>
            <p class="field-placeholder">{{ t('enterPromptToGenerate') }}</p>
            <div class="textarea-container">
              <div class="textarea-content">
                {{ currentImage?.prompt || t('enterPromptToGenerate') }}
              </div>
              <button 
                class="copy-btn"
                @click="handleCopy"
                :aria-label="t('copy')"
              >
                <l-img 
                  :src="'/static/images/copy_icon.png'" 
                  w="24px" 
                  h="24px"
                  class="copy-icon"
                />
                <span class="copy-text">{{ t('copy') }}</span>
              </button>
            </div>
          </div>

          <!-- Seed 显示区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('seedOptional') }}</label>
            <div class="field-value seed-value">
              {{ currentImage?.seed ?? '' }}
            </div>
          </div>
        </template>

        <!-- 增强模式专有字段 -->
        <template v-if="mode === 'enhance'">
          <!-- Prompt 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('prompt') }}</label>
            <p class="field-placeholder">{{ t('enterPromptToGenerate') }}</p>
            <div class="textarea-container">
              <div class="textarea-content">
                {{ currentImage?.prompt || enhanceConfig.prompt }}
              </div>
              <button 
                class="copy-btn"
                @click="handleCopy"
                :aria-label="t('copy')"
              >
                <l-img 
                  :src="'/static/images/copy_icon.png'" 
                  w="24px" 
                  h="24px"
                  class="copy-icon"
                />
                <span class="copy-text">{{ t('copy') }}</span>
              </button>
            </div>
          </div>

          <!-- Negative Prompt 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('negativePrompt') }}</label>
            <div class="textarea-container small">
              <div class="textarea-content">
                {{ enhanceConfig.negativePrompt }}
              </div>
            </div>
          </div>

          <!-- Creativity 区域 -->
          <div class="creativity-container">
            <label class="field-label">{{ t('creativity') }}</label>
            <span class="creativityText">{{ t('value') }} : {{ enhanceConfig.creativity }}</span>
          </div>

          <!-- Hand Fix 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('handFix') }}</label>
            <div class="field-value">
              {{ enhanceConfig.handFix ? t('enabled') : t('disabled') }}
            </div>
          </div>

          <!-- Seed 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('seedOptional') }}</label>
            <div class="field-value seed-value">
              {{ enhanceConfig.seed }}
            </div>
          </div>
        </template>

        <!-- 文生视频模式专有字段 -->
        <template v-if="mode === GenerationType.TEXT_TO_VIDEO">
          <!-- Prompt 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('prompt') }}</label>
            <div class="textarea-container">
              <div class="textarea-content">
                {{ currentVideo?.prompt || videoConfig.prompt }}
              </div>
              <button 
                class="copy-btn"
                @click="handleCopy"
                :aria-label="t('copy')"
              >
                <l-img 
                  :src="'/static/images/copy_icon.png'" 
                  w="24px" 
                  h="24px"
                  class="copy-icon"
                />
                <span class="copy-text">{{ t('copy') }}</span>
              </button>
            </div>
          </div>

          <!-- Model 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('model') }}</label>
            <div class="field-value">
              {{ videoConfig.model }}
            </div>
          </div>

          <!-- Resolution 区域 2 -->
          <div v-if="videoConfig.resolution" class="field-group">
            <label class="field-label">{{ t('resolution') }}</label>
            <div class="field-value resolution-box">
              {{ videoConfig.resolution }}
            </div>
          </div>

          <!-- Duration 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('duration') }}</label>
            <div class="field-value">
              {{ videoConfig.duration }}
            </div>
          </div>

          <!-- Video Dimensions 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('videoDimensions') }}</label>
            <div class="field-value dimension-value">
              <AspectRatio :aspect-ratio="videoConfig.dimensions" />
              {{ videoConfig.dimensions }}
            </div>
          </div>

          <!-- Frame Rate 区域 -->
          <div v-if="videoConfig.frameRate" class="field-group">
            <label class="field-label">{{ t('frameRate') }}</label>
            <div class="field-value">
              {{ videoConfig.frameRate }}
            </div>
          </div>

          <!-- Seed 区域 -->
          <div v-if="videoConfig.seed !== undefined && videoConfig.seed !== null" class="field-group">
            <label class="field-label">{{ t('seed') }}</label>
            <div class="field-value seed-value">
              {{ videoConfig.seed }}
            </div>
          </div>
        </template>

        <!-- 图生视频模式专有字段 -->
        <template v-if="mode === GenerationType.IMAGE_TO_VIDEO">
          <!-- Model 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('model') }}</label>
            <div class="field-value">
              {{ imgToVideoConfig.model }}
            </div>
          </div>

          <!-- Resolution 区域 -->
          <div v-if="imgToVideoConfig.resolution" class="field-group">
            <label class="field-label">{{ t('resolution') }}</label>
            <div class="field-value resolution-box">
              {{ imgToVideoConfig.resolution }}
            </div>
          </div>

          <!-- Duration 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('duration') }}</label>
            <div class="field-value resolution-box">
              {{ imgToVideoConfig.duration }}
            </div>
          </div>

          <!-- Video Dimensions 区域 -->
          <div class="field-group">
            <label class="field-label">{{ t('videoDimensions') }}</label>
            <div class="field-value dimension-value">
              <AspectRatio :aspect-ratio="imgToVideoConfig.dimensions" />
              {{ imgToVideoConfig.dimensions }}
            </div>
          </div>

          <!-- Frame Rate 区域 -->
          <div v-if="imgToVideoConfig.frameRate" class="field-group">
            <label class="field-label">{{ t('frameRate') }}</label>
            <div class="field-value">
              {{ imgToVideoConfig.frameRate }}
            </div>
          </div>

          <!-- Seed 区域 -->
          <div v-if="imgToVideoConfig.seed !== undefined && imgToVideoConfig.seed !== null" class="field-group">
            <label class="field-label">{{ t('seed') }}</label>
            <div class="field-value seed-value">
              {{ imgToVideoConfig.seed }}
            </div>
          </div>
        </template>


      </div>

    </div>
  </CommonDialog>
</template>

<script setup>
import { ref, computed, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import CommonDialog from '@/components/common-dialog.vue';
import LImg from '@/components/l-img.vue';
import LVideo from '@/components/l-video.vue';
import AspectRatio from '@/components/aspectRatio.vue';
import LButton from '@/components/l-button.vue';
import { showMessageSuccess } from '@/utils/ui-feedback';
import { copy } from '@/utils/util.js';
import { GenerationType } from '@/types/enums';

// 多语言支持
const { t } = useI18n();

// Props
const props = defineProps({
  modelValue: {
    type: Boolean,
    default: false
  },
  imageData: {
    type: Object,
    default: () => ({})
  },
  mode: {
    type: String,
    default: 'zoom', // 'zoom' | 'enhance' | 'edit' | GenerationType.TEXT_TO_VIDEO | GenerationType.IMAGE_TO_VIDEO
    validator: (value) => ['zoom', 'enhance', 'edit', GenerationType.TEXT_TO_VIDEO, GenerationType.IMAGE_TO_VIDEO].includes(value)
  }
});

watch(() => props.mode, (newVal) => {
  console.log('Mode changed:', newVal);
});

// Emits
const emit = defineEmits(['update:modelValue']);

// 响应式数据
const dialogVisible = ref(props.modelValue);

// 播放状态追踪（用于UI显示）
const isPlaying = ref(false);
const isImgToVideoPlaying = ref(false);

// 计算属性
const currentImage = computed(() => {
  console.log('Current image data in unified dialog:', props.imageData);
  return props.imageData || {};
});

const currentVideo = computed(() => {
  console.log('Current video data in unified dialog:', props.imageData);
  return props.imageData || {};
});

const scaleConfig = computed(() => {
  if (props.mode === 'zoom') {
    return props.imageData?.zoomConfig || { scale: 2.00 };
  } else {
    return props.imageData?.enhanceConfig || { scale: 2.00 };
  }
});

const enhanceConfig = computed(() => {
  return props.imageData?.enhanceConfig || {
    scale: 2.00,
    prompt: props.imageData?.prompt || 'masterpiece, best quality, highres',
    negativePrompt: 'worst quality, low quality, normal quality:2',
    creativity: 0.3,
    handFix: false,
    seed: props.imageData?.seed ?? ''
  };
});

const videoConfig = computed(() => {
  return props.imageData?.videoConfig || {
    prompt: props.imageData?.prompt || props.imageData?.description || '',
    model: props.imageData?.model || 'XMIND-G-VEO-2',
    resolution: props.imageData?.resolution || undefined,
    dimensions: props.imageData?.dimensions || '16:9',
    frameRate: undefined,
    duration: props.imageData?.duration || '5s',
    seed: props.imageData?.seed ?? undefined
  };
});

const imgToVideoConfig = computed(() => {
  // 图生视频使用videoConfig的数据
  return props.imageData?.videoConfig || {
    model: props.imageData?.model || 'XMIND-G-VEO-2',
    resolution: props.imageData?.resolution || undefined,
    dimensions: props.imageData?.dimensions || '16:9',
    frameRate: undefined,
    duration: '5s',
    seed: props.imageData?.seed ?? undefined
  };
});



// 编辑模式不需要响应式配置，只是显示模式

// 监听modelValue变化
watch(() => props.modelValue, (newVal) => {
  dialogVisible.value = newVal;
});

watch(dialogVisible, (newVal) => {
  emit('update:modelValue', newVal);
});

// 事件处理函数
const handleClose = () => {
  dialogVisible.value = false;
};

const handleImageError = (error) => {
  console.warn('Image load error:', error);
};

const handleVideoError = (error) => {
  console.warn('Video load error:', error);
};

// 视频事件处理函数
const handleVideoLoaded = (event) => {
  console.log('Video loaded:', event);
  // l-video 组件内部已处理时长
};

const handleVideoPlay = (event) => {
  isPlaying.value = true;
  console.log('Video playing:', event);
};

const handleVideoPause = (event) => {
  isPlaying.value = false;
  console.log('Video paused:', event);
};

// 图生视频专用事件处理函数
const handleImgToVideoLoaded = (event) => {
  console.log('ImgToVideo loaded:', event);
  // l-video 组件内部已处理时长
};

const handleImgToVideoPlay = (event) => {
  isImgToVideoPlaying.value = true;
  console.log('ImgToVideo playing:', event);
};

const handleImgToVideoPause = (event) => {
  isImgToVideoPlaying.value = false;
  console.log('ImgToVideo paused:', event);
};

const updateImgToVideoTime = (event) => {
  console.log('ImgToVideo time update:', event);
  // l-video 组件内部已处理时间更新
};



const formatTime = (time) => {
  if (!time || isNaN(time)) return '0:00';
  const minutes = Math.floor(time / 60);
  const seconds = Math.floor(time % 60);
  return `${minutes}:${seconds.toString().padStart(2, '0')}`;
};

// 监听视频播放时间
const updateTime = (event) => {
  console.log('Video time update:', event);
  // l-video 组件内部已处理时间更新
};

// 复制功能
const handleCopy = async () => {
  const textToCopy = currentImage.value?.prompt || currentVideo.value?.prompt || '';
  
  if (!textToCopy.trim()) {
    console.warn(t('nothingToCopy'));
    return;
  }

  try {
    copy(textToCopy);
    showMessageSuccess(t('copySuccess'));
  } catch (error) {
    console.error(t('copyFailed'), error);
  }
};

// 编辑模式只是显示，不需要事件处理
</script>

